import heapq

class NumberContainers:
    def __init__(self):
        self.idx_to_num = {}
        self.num_to_heap = {}

    def change(self, index: int, number: int) -> None:
        self.idx_to_num[index] = number
        if number not in self.num_to_heap:
            self.num_to_heap[number] = []
        heapq.heappush(self.num_to_heap[number], index)

    def find(self, number: int) -> int:
        if number not in self.num_to_heap:
            return -1
        h = self.num_to_heap[number]
        while h:
            idx = h[0]
            if self.idx_to_num.get(idx) == number:
                return idx
            heapq.heappop(h)
        return -1

class NumberContainers {
private:
    std::unordered_map<int, int> idx_to_num;
    std::unordered_map<int, std::set<int>> num_to_indices;
public:
    NumberContainers() {}

    void change(int index, int number) {
        if (idx_to_num.count(index)) {
            int old_num = idx_to_num[index];
            num_to_indices[old_num].erase(index);
        }
        idx_to_num[index] = number;
        num_to_indices[number].insert(index);
    }

    int find(int number) {
        if (!num_to_indices.count(number) || num_to_indices[number].empty()) return -1;
        return *num_to_indices[number].begin();
    }
};

class NumberContainers {
    private java.util.Map<Integer, Integer> idxToNum;
    private java.util.Map<Integer, java.util.TreeSet<Integer>> numToIndices;
    public NumberContainers() {
        idxToNum = new java.util.HashMap<>();
        numToIndices = new java.util.HashMap<>();
    }
    public void change(int index, int number) {
        if (idxToNum.containsKey(index)) {
            int oldNum = idxToNum.get(index);
            numToIndices.get(oldNum).remove(index);
        }
        idxToNum.put(index, number);
        numToIndices.computeIfAbsent(number, k -> new java.util.TreeSet<>()).add(index);
    }
    public int find(int number) {
        if (!numToIndices.containsKey(number) || numToIndices.get(number).isEmpty()) return -1;
        return numToIndices.get(number).first();
    }
}

var NumberContainers = function() {
    this.idxToNum = new Map();
    this.numToIndices = new Map();
};

NumberContainers.prototype.change = function(index, number) {
    this.idxToNum.set(index, number);
    if (!this.numToIndices.has(number)) {
        this.numToIndices.set(number, []);
    }
    this.numToIndices.get(number).push(index);
};

NumberContainers.prototype.find = function(number) {
    if (!this.numToIndices.has(number)) return -1;
    const arr = this.numToIndices.get(number);
    arr.sort((a, b) => a - b);
    while (arr.length > 0) {
        const idx = arr[0];
        if (this.idxToNum.get(idx) === number) return idx;
        arr.shift();
    }
    return -1;
};
